CREATE TABLE IF NOT EXISTS public."PPP_Pedidos_Entregados" (
  id    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tanda text,
  mt3   numeric
);
CREATE INDEX IF NOT EXISTS ppp_entr_tanda_idx
  ON public."PPP_Pedidos_Entregados" (upper(tanda));
ALTER TABLE public."PPP_Pedidos_Entregados" ENABLE ROW LEVEL SECURITY;
DO $pol$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
                 AND tablename='PPP_Pedidos_Entregados' AND policyname='ppp_entr_select') THEN
    CREATE POLICY "ppp_entr_select" ON public."PPP_Pedidos_Entregados"
      FOR SELECT TO anon, authenticated USING (true);
  END IF;
END $pol$;

-- 2465 filas

SELECT setval(pg_get_serial_sequence('public."PPP_Pedidos_Entregados"','id'),
              COALESCE((SELECT max(id) FROM public."PPP_Pedidos_Entregados"), 1));
